CREATE TABLE public.badges (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    code character varying(64) NOT NULL,
    name character varying(120) NOT NULL,
    description character varying(300) NOT NULL,
    required_streak_days integer NOT NULL,
    points integer DEFAULT 0 NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT badges_code_not_blank CHECK ((length(TRIM(BOTH FROM code)) > 0)),
    CONSTRAINT badges_description_not_blank CHECK ((length(TRIM(BOTH FROM description)) > 0)),
    CONSTRAINT badges_name_not_blank CHECK ((length(TRIM(BOTH FROM name)) > 0)),
    CONSTRAINT badges_points_nonnegative CHECK ((points >= 0)),
    CONSTRAINT badges_required_streak_positive CHECK ((required_streak_days > 0))
);


